use crate::common;
use rust_xlsxwriter::{ConditionalFormatIconSet, ConditionalFormatIconType, Workbook, XlsxError};

// Test an Excel 2010 extension icon set conditional format.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, row + 1)?;
    }

    // The ThreeTriangles icon set is only available in Excel 2010 and later.
    let conditional_format = ConditionalFormatIconSet::new()
        .set_icon_type(ConditionalFormatIconType::ThreeTriangles)
        .reverse_icons(true)
        .show_icons_only(true);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_cond_format28() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format28")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
